// <auto-generated> 逐帧动画（动图拆帧）的「游戏侧」代码生成器 </auto-generated>
//
// 【这份文件的模板文本是从哪来的】
//   用户拿到一份「别人新加了适配 gif 动画」的改造版（只有二进制，基线约 V0.2.37）。
//   我们把那份二进制当参考实现跑起来、导出它生成的源码，然后按本仓库的生成器风格重排成模板
//   （见 docs\逐帧动画_吸收设计.md 与 _art\anim_ref\runtime.ref.cs / patches.ref.cs）。
//   模板正文与参考实现的输出**逐字一致**，只把「角色相关」的少数字符串换成占位符：
//     @@SPACE@@ → 命名空间（Naming.Namespace）      @@PRE@@ → 类名前缀（Naming.ModId）
//     @@SLUG@@  → 角色 slug（Naming.CharSlug，日志标签用）
//   要改游戏里的行为，改下面两个模板（对着 _art\anim_ref 里的参考文件看）。
//
// 【为什么这些代码必须这么写】模板里的注释保留了参考实现踩过的坑（Godot 的 SpriteFrames.speed 是倍率不是 fps、
//   AnimatedSprite2D 不能嵌在静态立绘里、循环动画不能计时切回待机、篝火/商店的 _Ready 会无条件按 Spine 包节点…），
//   那些都是实测出来的，删掉注释等于把坑再踩一遍。

using System;
using System.Collections.Generic;
using System.Globalization;
using Sts2CharForge.Core.Profile;

namespace Sts2CharForge.Core.Generation;

/// <summary>
/// 「逐帧动画」要生成的两个源码文件 + 模组入口里那几行注册代码。
/// 只有 <see cref="Needs"/> 为真（勾了总开关且填了待机素材）时才生成 —— 不勾时生成结果与以前完全一样。
/// </summary>
public static class FrameAnimGen
{
    /// <summary>运行时（注册表 + 播放器）的文件名（不带扩展名）。</summary>
    public const string RuntimeFile = "FrameAnimRuntime";
    /// <summary>Harmony 补丁的文件名（不带扩展名）。</summary>
    public const string PatchesFile = "FrameAnimPatches";

    /// <summary>这份存档要不要逐帧动画：勾了总开关、而且**待机有素材**（待机是回退目标，必须有）。</summary>
    public static bool Needs(CharacterProfile p) => p.Animation.Enabled && p.Animation.HasAny;

    /// <summary>运行时源码（帧资源注册表 + 挂在角色视觉节点上的播放器）。</summary>
    public static string RuntimeSource(CharacterProfile p) => Fill(RuntimeTpl, p);

    /// <summary>补丁源码（战斗立绘挂载 / 触发翻译 / 死亡 / 篝火 / 商店 / 卡牌补触发）。</summary>
    public static string PatchesSource(CharacterProfile p) => Fill(PatchesTpl, p);

    /// <summary>
    /// 模组入口里那几行：四个常量（缩放 / Y 偏移 / 速度系数 / 篝火商店开关）+ 每个动作注册一次帧资源。
    /// 注入位置见 <see cref="PatchesGen.ModEntrySource"/>（在 <c>harmony.PatchAll</c> 之后）。
    /// </summary>
    public static List<string> RegistrationLines(CharacterProfile p, AnimFramesGen.Plan plan)
    {
        var n = Naming.From(p);
        var a = p.Animation;
        var lines = new List<string>
        {
            "",
            "// ==================== 逐帧动画（动图拆帧） ====================",
            "// 由工具生成：把本体的动画请求翻译成 AnimatedSprite2D 的逐帧播放。",
            "// 位置 / 缩放 / 速度都来自生成时的计划，和帧资源一致。",
            $"const float __animScale = {Num(plan.Scale)}f;",
            $"const float __animYOffset = {Num(plan.YOffset)}f;",
            $"const float __animSpeed = {Num(a.SpeedScale)}f;",
            $"const bool __animKeepRestShop = {(a.KeepRestAndShopAnim ? "true" : "false")};",
        };
        // 纹理过滤：参考实现这一步**漏了**（那个「最近邻」勾选框其实没生效 —— 实测 .import 和注册调用都没变），
        // 我们补上：像素画要用最近邻，线性过滤会在帧图被缩放时混出源里不存在的颜色、边缘发糊。
        string filter = a.NearestFilter ? "" : ", filter: Godot.CanvasItem.TextureFilterEnum.Linear";
        foreach (var one in plan.Anims)
        {
            string tres = $"res://images/characters/anim/{n.CharSlug}/{n.CharSlug}_{one.Anim}_frames.tres";
            lines.Add($"FrameAnimRegistry.Register({Lit.Str(n.CharSlug)}, {Lit.Str(one.Anim)}, {Lit.Str(tres)}, "
                + $"loop: {(one.Loop ? "true" : "false")}, scale: __animScale, yOffset: __animYOffset, "
                + $"speedScale: __animSpeed, keepRestShop: __animKeepRestShop{filter});");
        }
        lines.Add("// ==========================================================");
        return lines;
    }

    private static string Fill(string template, CharacterProfile p)
    {
        var n = Naming.From(p);
        // ★末尾必须补一个换行：C# 的原始字符串字面量（""" … """）**不包含**收尾定界符前面那个换行，
        // 而参考实现生成出来的文件末尾是带换行的（`…}\n}\n`）—— 少这一个字节，「逐字节一致」的验收就过不了。
        return template
            .Replace("@@SPACE@@", n.Namespace)
            .Replace("@@PRE@@", n.ModId)
            .Replace("@@SLUG@@", n.CharSlug) + "\n";
    }

    /// <summary>浮点常量按 3 位小数写（参考实现就是 <c>21.667f</c> 这种写法，两边文本保持一致）。</summary>
    private static string Num(double v) => v.ToString("0.###", CultureInfo.InvariantCulture);

    private const string RuntimeTpl = """
// <auto-generated> 逐帧动画运行时：注册表 + 播放器 </auto-generated>
// 由 Sts2CharForge 生成；改了配置会重新生成，要改逻辑请改工具里的 FrameAnimGen。
#nullable enable
using System;
using System.Collections.Generic;
using System.Linq;
using Godot;
using MegaCrit.Sts2.Core.Logging;

namespace @@SPACE@@;

/// <summary>帧动画注册表：角色 id -> 各状态的帧资源。多个自建角色各注册各的，互不干扰。</summary>
public static class FrameAnimRegistry
{
    private static readonly Dictionary<string, CharDef> Defs = new(StringComparer.OrdinalIgnoreCase);

    /// <summary>
    /// 单独注册一个状态的帧动画。
    /// speedScale：播放速度系数，1 = 动图原速；holdAtEnd：播完定格在最后一帧（死亡用）。
    /// filter：纹理过滤。像素画用 Nearest —— 帧图在游戏里会被缩放，线性过滤会混出
    ///         大量源里不存在的颜色、边缘发糊（实测 9704 色 vs 256 色）。
    /// </summary>
    public static void Register(string charId, string animName, string tresPath,
        bool loop = false, float scale = 1f, float yOffset = -97f, float speedScale = 1f,
        bool holdAtEnd = false, CanvasItem.TextureFilterEnum filter = CanvasItem.TextureFilterEnum.Nearest,
        bool keepRestShop = true)
    {
        if (!Defs.TryGetValue(charId, out var def)) Defs[charId] = def = new CharDef(charId);
        def.Animations[animName] = new AnimDef(animName, tresPath, loop, holdAtEnd);
        def.Scale = scale;
        def.YOffset = yOffset;
        def.SpeedScale = speedScale <= 0.01f ? 1f : speedScale;
        def.Filter = filter;
        def.KeepRestShop = keepRestShop;
    }

    /// <summary>把节点 / 场景名规范化成 id：去掉 Visuals / Merchant / RestSite 之类后缀，转小写。</summary>
    public static string NormalizeId(string raw)
    {
        string s = raw.Trim();
        foreach (string suffix in new[] { "Visuals", "Merchant", "RestSite", "Rest", "Character" })
            if (s.EndsWith(suffix, StringComparison.OrdinalIgnoreCase)) s = s[..^suffix.Length];
        return s.ToLowerInvariant();
    }

    internal static bool TryGet(string charId, out CharDef def)
    {
        if (Defs.TryGetValue(charId, out var d)) { def = d; return true; }
        def = null!;
        return false;
    }

    public sealed class CharDef(string charId)
    {
        public readonly string CharId = charId;
        public readonly Dictionary<string, AnimDef> Animations = new(StringComparer.Ordinal);
        public float Scale = 1f;
        public float YOffset = -97f;
        public float SpeedScale = 1f;
        public CanvasItem.TextureFilterEnum Filter = CanvasItem.TextureFilterEnum.Nearest;
        /// <summary>true = 在篝火 / 商店里不理会本体发来的 Idle，保持自己的动画。</summary>
        public bool KeepRestShop = true;

        /// <summary>某个状态没做素材时退回哪个，尽量别让角色定格。</summary>
        public static string? FallbackFor(string anim) => anim switch
        {
            "low_health_loop" => "idle_loop",
            "relaxed_loop"    => "idle_loop",
            "overgrowth_loop" => "idle_loop",
            "hive_loop"       => "idle_loop",
            "glory_loop"      => "idle_loop",
            "revive"          => "idle_loop",
            "cast"            => "attack",
            "hurt"            => "idle_loop",   // 没做受击素材：挨打保持待机
            _                 => null,
        };

        /// <summary>按名字找一条动画，找不到就沿回退链找；都没有则返回 idle。</summary>
        public AnimDef? Resolve(string anim)
        {
            if (Animations.TryGetValue(anim, out var d)) return d;
            string? fb = FallbackFor(anim);
            for (int guard = 0; guard < 4 && fb is not null; guard++)
            {
                if (Animations.TryGetValue(fb, out var d2)) return d2;
                if (fb == "idle_loop") break;
                fb = FallbackFor(fb);
            }
            return Animations.TryGetValue("idle_loop", out var idle) ? idle : null;
        }
    }

    public sealed record AnimDef(string Name, string Path, bool Loop, bool HoldAtEnd = false);
}

/// <summary>把 AnimatedSprite2D 挂到角色视觉节点上并驱动它。</summary>
public sealed partial class FrameAnimPlayer : Node
{
    private FrameAnimRegistry.CharDef _def = null!;
    private AnimatedSprite2D _sprite = null!;
    private Sprite2D? _staticBody;
    private string _current = "";
    private double _busyLeft;
    private double _verifyClock;
    private bool _verified;
    private bool _rollback;
    private bool _holdAtEnd;
    private bool _held;
    /// <summary>当前这条是篝火 / 商店的场景动画，且开关要求保持 —— 这时不接受 Idle。</summary>
    private bool _sceneLocked;

    private static readonly Dictionary<string, SpriteFrames?> Cache = new(StringComparer.Ordinal);
    private static readonly HashSet<string> Normalized = new(StringComparer.Ordinal);
    private static readonly HashSet<string> SpeedApplied = new(StringComparer.Ordinal);

    /// <summary>当前动画一轮多少秒（本体 GetCurrentAnimationLength 会用到）。</summary>
    public double CurrentLoopSeconds { get; private set; }

    /// <summary>给指定角色的视觉节点装上帧动画；已经装过就直接返回。</summary>
    public static FrameAnimPlayer? Attach(Node visualsRoot, FrameAnimRegistry.CharDef def)
    {
        if (visualsRoot.GetNodeOrNull<FrameAnimPlayer>("__FrameAnimPlayer") is { } existing) return existing;

        // 战斗立绘有 %Visuals；篝火 / 商店没有（本体拿第一个子节点当 Spine 用），逐级回退
        var body = visualsRoot.GetNodeOrNull<Node2D>("%Visuals")
                   ?? visualsRoot.GetNodeOrNull<Node2D>("Visuals")
                   ?? FindFirstSprite(visualsRoot)
                   ?? (visualsRoot as Node2D);
        Log.Info($"[@@SLUG@@_anim] 挂载: 根={visualsRoot.Name}({visualsRoot.GetClass()}) " +
                 $"body={(body is null ? "null" : body.Name + "(" + body.GetClass() + ")")} " +
                 $"子节点={string.Join(",", Enumerable.Range(0, visualsRoot.GetChildCount()).Select(i => visualsRoot.GetChild(i).Name.ToString()))}");
        if (body is null)
        {
            Log.Warn("[@@SLUG@@_anim] 找不到可用的视觉节点，帧动画装不上");
            return null;
        }

        var idle = def.Resolve("idle_loop");
        if (idle is null)
        {
            Log.Warn("[@@SLUG@@_anim] 没有任何已注册的帧动画");
            return null;
        }
        if (LoadFrames(idle.Path) is null)
        {
            Log.Warn($"[@@SLUG@@_anim] 载入帧资源失败 {idle.Path}");
            return null;
        }

        AnimatedSprite2D asp;
        if (body is Sprite2D s2d)
        {
            // 关键：与静态图**同级**、插在它后面一位（画在它上面），不要嵌进去 ——
            // 嵌进去的话把静态图 Visible=false 会连动画一起隐藏，角色就整个消失了。
            asp = new AnimatedSprite2D
            {
                Name = "__FrameAnimSprite",
                Centered = true,
                Position = s2d.Position,
                Scale = s2d.Scale,
                ZIndex = s2d.ZIndex,
                Visible = false,
            };
            if (s2d.GetParent() is { } sp)
            {
                sp.AddChild(asp);
                sp.MoveChild(asp, s2d.GetIndex() + 1);
            }
            else s2d.AddChild(asp);
        }
        else if (body is AnimatedSprite2D already) asp = already;
        else
        {
            asp = new AnimatedSprite2D
            {
                Name = "__FrameAnimSprite",
                Centered = true,
                Position = new Vector2(0f, def.YOffset),
                Scale = new Vector2(def.Scale, def.Scale),
                Visible = false,
            };
            body.AddChild(asp);
        }

        var player = new FrameAnimPlayer
        {
            Name = "__FrameAnimPlayer",
            _def = def,
            _sprite = asp,
            _staticBody = body as Sprite2D,
        };
        visualsRoot.AddChild(player);

        // 纹理过滤设在根节点上，整棵视觉子树跟着走（像素画要最近邻，否则缩放会糊）
        if (visualsRoot is CanvasItem ci) ci.TextureFilter = def.Filter;

        player.Play("idle_loop");

        // 自检：把关键状态写进游戏日志，出问题时有据可查
        var frames = asp.SpriteFrames;
        int fc = frames is null ? -1 : frames.GetFrameCount(asp.Animation);
        var tex0 = frames is null || fc <= 0 ? null : frames.GetFrameTexture(asp.Animation, 0);
        Log.Info($"[@@SLUG@@_anim] 自检 动画={asp.Animation} 帧数={fc} " +
                 $"帧图={(tex0 is null ? "null" : tex0.GetSize().ToString())} 位置={asp.Position} " +
                 $"父={asp.GetParent()?.Name} 树中可见={asp.IsVisibleInTree()}");
        if (fc <= 0 || tex0 is null)
        {
            Log.Warn("[@@SLUG@@_anim] 帧数据不完整，保留原静态立绘，帧动画停用");
            asp.QueueFree();
            player.QueueFree();
            return null;
        }
        asp.Visible = true;
        Log.Info("[@@SLUG@@_anim] 帧动画已挂上（视觉节点 = " + body.GetClass() + "）");
        return player;
    }

    private static Sprite2D? FindFirstSprite(Node root)
    {
        int n = root.GetChildCount();
        for (int i = 0; i < n; i++) if (root.GetChild(i) is Sprite2D s) return s;
        return null;
    }

    public void Play(string anim)
    {
        var pick = _def.Resolve(anim);
        if (pick is null) return;

        var frames = LoadFramesFor(pick.Path);
        if (frames is null) return;
        if (!frames.HasAnimation(pick.Name))
        {
            var names = frames.GetAnimationNames();
            if (names.Length == 0)
            {
                Log.Warn($"[@@SLUG@@_anim] {pick.Path} 里没有任何动画");
                return;
            }
            pick = pick with { Name = names[0] };
        }

        // 循环动画已经在播同一条就别重启；定格中的也保持不动
        if (_current == pick.Name && _sprite.IsPlaying()) return;
        if (_current == pick.Name && _held) return;

        _sprite.SpriteFrames = frames;
        frames.SetAnimationLoop(pick.Name, pick.Loop);
        _sprite.Animation = pick.Name;
        _held = false;
        _sprite.Play();
        _current = pick.Name;
        _holdAtEnd = pick.HoldAtEnd;
        _sceneLocked = _def.KeepRestShop && pick.Name is "overgrowth_loop" or "hive_loop" or "glory_loop" or "relaxed_loop";
        Log.Info($"[@@SLUG@@_anim] 播放: 请求={anim} 实际={pick.Name} 定格={pick.HoldAtEnd} 场景锁={_sceneLocked}");

        int n = frames.GetFrameCount(pick.Name);
        double total = 0.0;
        for (int i = 0; i < n; i++) total += frames.GetFrameDuration(pick.Name, i);
        CurrentLoopSeconds = total;
        // 只有「单次」动画才需要计时来决定什么时候回待机。
        // 循环动画（待机 / 篝火 / 商店）交给 SpriteFrames 自己循环，**绝不能**到时切回待机：
        // 踩过的坑：这里原来对循环动画也计时，一圈跑完 _Process 就主动 Play("idle_loop")，
        // 表现是「篝火 / 商店先播专属动画，过一会儿（= 一圈时长）变成待机」。
        _busyLeft = pick.Loop ? 0.0 : total;
    }

    /// <summary>把本体的触发名翻译成动画名并播放。</summary>
    public void Trigger(string trigger)
    {
        if (IsBusy && trigger is "Idle") return;   // 受击 / 死亡这类别被 Idle 打断
        // 篝火 / 商店：本体进场景后会再发一次 Idle，把刚播上的场景动画顶掉
        //（表现是「先动一下，然后变成待机」）。开关要求保持时就不理会它。
        Log.Info($"[@@SLUG@@_anim] 收到触发 '{trigger}'（当前={_current} 场景锁={_sceneLocked}");
        if (_sceneLocked && trigger is "Idle" or "Relaxed") return;
        string? anim = trigger switch
        {
            "Attack"  => "attack",
            "Cast"    => "cast",
            "PowerUp" => "cast",
            "Hit"     => "hurt",
            "Dead"    => "die",
            "Revive"  => "revive",
            "Idle"    => "idle_loop",
            "Relaxed" => "relaxed_loop",
            _         => null,
        };
        if (anim is not null) Play(anim);
    }

    public bool IsBusy => _busyLeft > 0.0;

    /// <summary>非循环动画播完：需要定格的定格（死亡），否则回待机。</summary>
    public override void _Process(double delta)
    {
        // 挂上后 1 秒检查一次：动画确实在渲染才把静态图收掉；
        // 没在渲染就整个回滚，绝不留下「角色消失」的状态。
        if (!_verified)
        {
            _verifyClock += delta;
            if (_verifyClock < 1.0) return;
            _verified = true;
            if (_sprite.IsPlaying() && _sprite.IsVisibleInTree())
            {
                if (_staticBody is { } st) st.Visible = false;
                Log.Info("[@@SLUG@@_anim] 动画渲染确认 OK -> 静态立绘已收掉");
            }
            else
            {
                Log.Warn("[@@SLUG@@_anim] 动画未在渲染 -> 回滚，保留静态立绘");
                _sprite.Visible = false;
                _rollback = true;
            }
            return;
        }

        // _busyLeft 只对「单次」动画有效（循环动画一直是 0）
        if (_rollback || _current.Length == 0 || _busyLeft <= 0.0) return;
        _busyLeft -= delta;
        if (_busyLeft > 0.0) return;
        _busyLeft = 0.0;
        if (_holdAtEnd)
        {
            // 定格在最后一帧（本体 Spine 的 die 状态就是没有后继状态）
            int n = _sprite.SpriteFrames?.GetFrameCount(_current) ?? 0;
            _sprite.Stop();
            if (n > 0) _sprite.Frame = n - 1;
            _held = true;
            Log.Info($"[@@SLUG@@_anim] '{_current}' 播完，定格在最后一帧");
        }
        else Play("idle_loop");
    }

    private static SpriteFrames? LoadFrames(string path)
    {
        if (Cache.TryGetValue(path, out var cached)) return cached;
        var res = ResourceLoader.Exists(path) ? ResourceLoader.Load<SpriteFrames>(path) : null;
        if (res is null) Log.Warn($"[@@SLUG@@_anim] 帧资源不存在或不是 SpriteFrames: {path}");
        Cache[path] = res;
        return res;
    }

    /// <summary>
    /// 取帧资源，归一化成「每帧秒数、speed=1」，再按 SpeedScale 校正整体速度。
    /// 关键：Godot 的 SpriteFrames.speed **不是 fps 而是倍率**
    ///（实测 60 帧×0.1s：speed=1 周期 6.02s，speed=30 只有 0.215s）。
    /// 早期把它当 fps 填了 30，动画被额外加速 30 倍，怎么调速度系数都不对。
    /// </summary>
    private SpriteFrames? LoadFramesFor(string path)
    {
        var frames = LoadFrames(path);
        if (frames is null) return null;
        float speedScale = _def.SpeedScale <= 0.01f ? 1f : _def.SpeedScale;

        if (Normalized.Add(path))
        {
            foreach (var anim in frames.GetAnimationNames())
            {
                int n = frames.GetFrameCount(anim);
                if (n <= 0) continue;
                double curSpeed = frames.GetAnimationSpeed(anim);
                if (curSpeed <= 0.001) curSpeed = 1.0;
                var texs = new Texture2D[n];
                var durs = new double[n];
                for (int i = 0; i < n; i++)
                {
                    texs[i] = frames.GetFrameTexture(anim, i);
                    durs[i] = frames.GetFrameDuration(anim, i);   // 本来就是秒数，不要再乘 speed
                }
                bool loop = frames.GetAnimationLoop(anim);
                frames.RemoveAnimation(anim);
                frames.AddAnimation(anim);
                for (int i = 0; i < n; i++) frames.AddFrame(anim, texs[i], (float)durs[i]);
                frames.SetAnimationSpeed(anim, 1.0);
                frames.SetAnimationLoop(anim, loop);
                Log.Info($"[@@SLUG@@_anim] 归一化 '{anim}': 原 speed={curSpeed:0.###} -> 1，周期 {durs[0] * n:F3}s");
            }
        }

        if (Mathf.Abs(speedScale - 1f) < 0.001f) return frames;
        if (!SpeedApplied.Add(path)) return frames;
        foreach (var anim in frames.GetAnimationNames())
        {
            int n = frames.GetFrameCount(anim);
            if (n <= 0) continue;
            var texs = new Texture2D[n];
            var durs = new double[n];
            for (int i = 0; i < n; i++)
            {
                texs[i] = frames.GetFrameTexture(anim, i);
                durs[i] = frames.GetFrameDuration(anim, i);
            }
            bool loop = frames.GetAnimationLoop(anim);
            frames.RemoveAnimation(anim);
            frames.AddAnimation(anim);
            for (int i = 0; i < n; i++) frames.AddFrame(anim, texs[i], (float)(durs[i] / speedScale));
            frames.SetAnimationSpeed(anim, 1.0);
            frames.SetAnimationLoop(anim, loop);
        }
        Log.Info($"[@@SLUG@@_anim] 速度系数 {speedScale:0.###} 已应用");
        return frames;
    }
}
""";

