/// <summary>找直接子节点里第一个 SpineSprite。</summary>
internal static class FrameAnimSpineProbe
{
    public static Node2D? FindDirectSpineChild(Node host)
    {
        int n = host.GetChildCount();
        for (int i = 0; i < n; i++)
            if (host.GetChild(i) is Node2D n2 && n2.GetClass() == "SpineSprite") return n2;
        return null;
    }

    /// <summary>
    /// 反射读本体私有字段（V0.2.227：篝火 FlipX 兜底用）。字段找不到 / 名字变了就返回 null，
    /// 调用方退回「照常执行本体」—— 绝不能因为读不到字段把游戏改坏。
    /// </summary>
    public static AccessTools.FieldRef<T, F>? TryFieldRef<T, F>(string fieldName) where T : class
    {
        try
        {
            return AccessTools.FieldRefAccess<T, F>(fieldName);
        }
        catch (Exception e)
        {
            Log.Warn($"[@@SLUG@@_anim] 读不到 {typeof(T).Name}.{fieldName}：{e.Message}");
            return null;
        }
    }

    /// <summary>水平镜像：Scale.X 与 Position.X 一起取反（和本体翻 Spine 子节点同一套做法）。</summary>
    public static void MirrorX(Node2D? node)
    {
        if (node is null || !GodotObject.IsInstanceValid(node)) return;
        Vector2 scale = node.Scale;
        scale.X = 0f - scale.X;
        node.Scale = scale;
        Vector2 pos = node.Position;
        pos.X = 0f - pos.X;
        node.Position = pos;
    }
}

/// <summary>
/// 从场景文件路径推出角色 id。生成器产出的场景按用途命名：
/// <c>creature_visuals/&lt;id&gt;.tscn</c>、<c>rest_site/characters/&lt;id&gt;_rest_site.tscn</c>、
/// <c>merchant/characters/&lt;id&gt;_merchant.tscn</c>。
/// 先按文件名推出的 id 最可靠；推不出来才退回用节点名。
/// </summary>
internal static class FrameAnimSceneId
{
    private static readonly System.Collections.Generic.Dictionary<ulong, string> Memo = new();

    public static string Resolve(Node node)
    {
        ulong key = node.GetInstanceId();
        if (Memo.TryGetValue(key, out var cached)) return cached;
        string id = FromSceneFile(node.SceneFilePath);
        if (id.Length == 0) id = FrameAnimRegistry.NormalizeId(node.Name.ToString());
        Memo[key] = id;
        Log.Info($"[@@SLUG@@_anim] 场景 id: 节点='{node.Name}' 场景='{node.SceneFilePath}' -> '{id}'");
        return id;
    }

    /// <summary>从场景文件名推 id：砍掉用途后缀再规范化。</summary>
    public static string FromSceneFile(string path)
    {
        if (string.IsNullOrEmpty(path)) return "";
        string name = path.GetFile().GetBaseName();
        foreach (string suffix in new[] { "_rest_site", "_restsite", "_merchant", "_visuals", "_selectbg" })
            if (name.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
            {
                name = name[..^suffix.Length];
                break;
            }
        return FrameAnimRegistry.NormalizeId(name);
    }
}
""";
